-- PostgreSQL 15+; synthetic business references only.
CREATE SCHEMA IF NOT EXISTS trade_demo;
CREATE TABLE IF NOT EXISTS trade_demo.programmes(programme_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,programme_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,service_type TEXT NOT NULL CHECK(service_type IN('export_readiness','market_access','quality_support','trade_fair','industrial_advisory','other')),starts_on DATE,ends_on DATE,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','active','paused','closed')),CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS trade_demo.applicant_refs(applicant_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,applicant_token TEXT NOT NULL UNIQUE,business_type TEXT NOT NULL CHECK(business_type IN('micro','small','medium','large','cooperative','other')),sector_code TEXT NOT NULL,locality_code TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS trade_demo.applications(application_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_ref TEXT NOT NULL UNIQUE,programme_id BIGINT NOT NULL REFERENCES trade_demo.programmes(programme_id) ON DELETE RESTRICT,applicant_id BIGINT NOT NULL REFERENCES trade_demo.applicant_refs(applicant_id) ON DELETE RESTRICT,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','in_review','accepted','declined','withdrawn')),decision_note TEXT,UNIQUE(programme_id,applicant_id));
CREATE TABLE IF NOT EXISTS trade_demo.milestones(milestone_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_ref TEXT NOT NULL UNIQUE,application_id BIGINT NOT NULL REFERENCES trade_demo.applications(application_id) ON DELETE RESTRICT,milestone_type TEXT NOT NULL CHECK(milestone_type IN('diagnostic','training','quality_review','buyer_introduction','follow_up','other')),owner_ref TEXT NOT NULL,due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','completed','cancelled')),completed_at TIMESTAMPTZ,summary TEXT NOT NULL,CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS trade_demo.milestone_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_id BIGINT NOT NULL REFERENCES trade_demo.milestones(milestone_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','completed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_trade_applications_programme ON trade_demo.applications(programme_id,status,submitted_at DESC);
CREATE INDEX IF NOT EXISTS ix_trade_milestone_due ON trade_demo.milestones(status,due_date) WHERE status NOT IN('completed','cancelled');
CREATE INDEX IF NOT EXISTS ix_trade_events_history ON trade_demo.milestone_events(milestone_id,happened_at DESC,event_id DESC);